SET SESSION TRANSACTION READ ONLY;
START TRANSACTION WITH CONSISTENT SNAPSHOT;
SELECT 'ACTIVE_DUPLICATE_PRIMARY_EMAILS',x.bean_module,COUNT(*) AS duplicate_groups,SUM(n-1) AS excess_records FROM (SELECT r.bean_module,BINARY LOWER(e.email_address) AS email,COUNT(DISTINCT r.bean_id) AS n FROM email_addr_bean_rel r JOIN email_addresses e ON e.id=r.email_address_id AND e.deleted=0 LEFT JOIN contacts c ON c.id=r.bean_id AND r.bean_module='Contacts' LEFT JOIN leads l ON l.id=r.bean_id AND r.bean_module='Leads' WHERE r.deleted=0 AND r.primary_address=1 AND ((r.bean_module='Contacts' AND c.deleted=0) OR (r.bean_module='Leads' AND l.deleted=0)) GROUP BY r.bean_module,email HAVING n>1) x GROUP BY x.bean_module;
SELECT 'ACTIVE_DUPLICATE_ACCOUNT_NAMES',COUNT(*) AS duplicate_groups,SUM(n-1) AS excess_records FROM (SELECT BINARY LOWER(name) AS k,COUNT(*) AS n FROM accounts WHERE deleted=0 GROUP BY k HAVING n>1) x;
SELECT 'EMPTY_ACCOUNT_NAMES',SUM(name IS NULL),SUM(name='') FROM accounts WHERE deleted=0;
SELECT 'CONTACT_PHONE_OVERFLOW',SUM(CHAR_LENGTH(phone_work)>25),SUM(CHAR_LENGTH(phone_mobile)>25) FROM contacts WHERE deleted=0;
SELECT 'LEAD_PHONE_OVERFLOW',SUM(CHAR_LENGTH(phone_work)>25),SUM(CHAR_LENGTH(phone_mobile)>25) FROM leads WHERE deleted=0;
SELECT 'EMAIL_RELATIONS',bean_module,COUNT(*) AS links FROM emails_beans WHERE deleted=0 GROUP BY bean_module;
SELECT 'CALL_PARENTS',parent_type,COUNT(*) AS calls FROM calls WHERE deleted=0 GROUP BY parent_type;
SELECT 'MEETING_PARENTS',parent_type,COUNT(*) AS meetings FROM meetings WHERE deleted=0 GROUP BY parent_type;
SELECT 'LEAD_CONVERSION_LINKS',SUM(converted=1),SUM(contact_id IS NOT NULL AND contact_id<>''),SUM(account_id IS NOT NULL AND account_id<>''),SUM(opportunity_id IS NOT NULL AND opportunity_id<>'') FROM leads WHERE deleted=0;
SELECT 'BROKEN_CONVERSION_CONTACTS',COUNT(*) FROM leads l LEFT JOIN contacts c ON c.id=l.contact_id WHERE l.deleted=0 AND l.contact_id IS NOT NULL AND l.contact_id<>'' AND c.id IS NULL;
SELECT 'INVOICE_MISSING_AMOUNTS',COUNT(*) AS active_invoices,SUM(total_amount IS NULL) AS total_null,SUM(billing_account_id IS NULL OR billing_account_id='') AS account_missing FROM aos_invoices WHERE deleted=0;
SELECT 'INVOICE_LINE_ITEMS',SUM(q.deleted=0) AS active_lines,SUM(q.deleted=1 AND i.deleted=0) AS deleted_lines_on_active_invoices FROM aos_products_quotes q LEFT JOIN aos_invoices i ON i.id=q.parent_id WHERE q.parent_type='AOS_Invoices';
SELECT 'INVOICE_ACCOUNTS',COUNT(*) AS invoices,SUM(a.id IS NULL) AS missing_accounts,SUM(a.deleted=1) AS deleted_accounts FROM aos_invoices i LEFT JOIN accounts a ON a.id=i.billing_account_id WHERE i.deleted=0;
SELECT 'EMAIL_BODIES',COUNT(*) AS messages,SUM(t.email_id IS NULL) AS missing_text_rows,SUM(COALESCE(t.description,'')='' AND COALESCE(t.description_html,'')='') AS empty_bodies FROM emails e LEFT JOIN emails_text t ON t.email_id=e.id WHERE e.deleted=0;
SELECT 'EMAIL_DIRECTIONS',type,status,COUNT(*) FROM emails WHERE deleted=0 GROUP BY type,status;
SELECT 'AUDIT_COUNTS', 'contacts',COUNT(*) FROM contacts_audit;
COMMIT;
